		n = read_title();
		KT_ASSERT(find_text(brmeta, n, "ep=ok") > 0);
		KT_ASSERT(find_text(brmeta, n, "key=BCVxsr7N_eNgVRqvHtD0zTZsEc6-VV-JvLexhqUzORcxaOzi6-AYWXvTBHm4bjyPjs7Vd8pZGH6SRpkNtoIAiw4") > 0);
		KT_ASSERT(find_text(brmeta, n, "auth=BTBZMqHH6r4Tts7J_aSIgg") > 0);
		KT_ASSERT(find_text(brmeta, n, "again=same") > 0);
		KT_ASSERT(find_text(brmeta, n, "push=push:push from the test \xe3\x81\x82") > 0);
		KT_ASSERT(find_text(brmeta, n, "old=push:aesgcm too") > 0);
		KT_ASSERT(push_hello >= 1);
		KT_ASSERT(push_acked >= 1);
		n = push_acked;
		KT_ASSERT_EQ(run_browser(&page2, lines, NULL, push_check2), 0);
		desk_down();
		tm_printf((UB*)"  push service: %d hello (%d again), %d acknowledged, %d unregistered\n",
			  push_hello, push_back, push_acked, push_unreg);
		KT_ASSERT(push_back >= 1);
