	KT_ASSERT(find_text(brmeta, n, "unreg=true") > 0);
	KT_ASSERT(find_text(brmeta, n, "err=") < 0);
	srv_end();
	KT_ASSERT_ER(ob_del_obj(&page), E_OK);
