	if ( fs_stat(SKPROG, &st) < EX_OK ) {
		KT_SKIP("the engine is not built (make BROWSER=1)");
	}
#if !TS_NETSTACK_NETBSD
	KT_SKIP("the network stack has no IPv6 (NETSTACK=lwip)");
#endif
